<template><AppShell :title="pageTitle"><template #default="{ can, setError }"><v-tabs v-model="tab" grow density="compact"><v-tab value="input">입력</v-tab><v-tab value="list">조회</v-tab><v-tab value="stats">통계</v-tab></v-tabs><v-window v-model="tab" class="mt-4"><v-window-item value="input"><v-form @submit.prevent="save(setError)"><v-text-field v-model="form.work_date" type="date" label="작업일" variant="outlined"/><v-select v-model="form.product_id" :items="products" item-title="name" item-value="id" label="제품" variant="outlined"/><v-select v-model="form.worker_id" :items="workers" item-title="name" item-value="id" label="작업자" variant="outlined"/><div class="d-flex ga-2"><v-number-input v-model="form.production_quantity" label="생산" variant="outlined" :min="0"/><v-number-input v-model="form.waste_quantity" label="폐기" variant="outlined" :min="0"/><v-number-input v-model="form.loss_quantity" label="로스" variant="outlined" :min="0"/></div><v-text-field v-if="form.waste_quantity>0" v-model="form.waste_reason" label="폐기 사유" variant="outlined"/><v-text-field v-if="form.loss_quantity>0" v-model="form.loss_reason" label="로스 사유" variant="outlined"/><v-textarea v-model="form.note" label="메모" variant="outlined" rows="2"/><v-btn v-if="can('production.create')" type="submit" block :loading="saving">기록 저장</v-btn></v-form></v-window-item><v-window-item value="list"><v-text-field v-model="filterDate" type="date" label="날짜 필터" variant="outlined" clearable @update:model-value="load"/><v-list lines="three"><v-list-item v-for="r in records" :key="r.id"><v-list-item-title>{{ r.product?.name }} · {{ r.worker?.name }}</v-list-item-title><v-list-item-subtitle>{{ r.work_date }} | 생산 {{ r.production_quantity }} / 폐기 {{ r.waste_quantity }} / 로스 {{ r.loss_quantity }}</v-list-item-subtitle><template #append><v-btn v-if="can('production.delete')" icon="mdi-delete-outline" size="small" variant="text" @click="remove(r,setError)"/></template></v-list-item></v-list><v-empty-state v-if="!records.length" title="기록이 없습니다." icon="mdi-clipboard-text-outline"/></v-window-item><v-window-item value="stats"><v-card variant="outlined"><v-card-text><div class="text-caption">조회 기록 합계</div><div class="text-h5 font-weight-bold">생산 {{ totals.production }}개</div><div class="text-body-2 mt-2">폐기 {{ totals.waste }}개 · 로스 {{ totals.loss }}개</div></v-card-text></v-card></v-window-item></v-window></template></AppShell></template>
<script setup>
import {computed,onMounted,ref} from 'vue';import AppShell from '../../components/layout/AppShell.vue';const pageTitle='생산·폐기 관리';const tab=ref('input'),records=ref([]),products=ref([]),workers=ref([]),saving=ref(false),filterDate=ref('');const form=ref({work_date:new Date().toISOString().slice(0,10),product_id:null,worker_id:null,production_quantity:0,waste_quantity:0,loss_quantity:0,waste_reason:'',loss_reason:'',note:''});const totals=computed(()=>records.value.reduce((a,r)=>({production:a.production+r.production_quantity,waste:a.waste+r.waste_quantity,loss:a.loss+r.loss_quantity}),{production:0,waste:0,loss:0}));async function load(){const [a,b]=await Promise.all([window.axios.get('/tillwhite/api/production',{params:{date:filterDate.value||undefined}}),window.axios.get('/tillwhite/api/production/options')]);records.value=a.data.records;products.value=b.data.products;workers.value=b.data.workers;}async function save(setError){saving.value=true;try{await window.axios.post('/tillwhite/api/production',form.value);form.value.production_quantity=form.value.waste_quantity=form.value.loss_quantity=0;await load();tab.value='list';}catch(e){setError(e.response?.data?.message??'저장에 실패했습니다.');}finally{saving.value=false;}}async function remove(r,setError){if(!confirm('이 기록을 삭제할까요?'))return;try{await window.axios.delete(`/tillwhite/api/production/${r.id}`);await load();}catch(e){setError(e.response?.data?.message??'삭제에 실패했습니다.');}}onMounted(load);
</script>
